  "w2b:2": {"read": [{"label": "Mathematics for Machine Learning — ch. 5, Vector Calculus, the chain-rule section, to check your derivation only after you have an answer", "url": "https://mml-book.github.io/book/mml-book.pdf", "m": 10}], "aieng": [{"label": "AI Engineering from Scratch, phase 1, lesson 05: Chain Rule and Autodiff", "url": "https://aiengineeringfromscratch.com/lesson?path=phases%2F01-math-foundations%2F05-chain-rule-and-autodiff", "m": 20}], "sd": [], "figIdea": "sigma(x) plotted with sigma(x)(1-sigma(x)) underneath: the derivative peaks where the forward value sits near 0.5 and flattens at the saturated ends.", "figs": ["sigmoidDerivative"], "res": [{"kind": "video", "req": true, "label": "Chain rule, with the power rule on a nested function", "url": "https://www.youtube.com/watch?v=0T0QrHO56qg", "m": 6, "why": "The tool the derivation needs, in six minutes: outer derivative times inner derivative, on a power of an expression.", "yt": {"id": "0T0QrHO56qg", "ch": "Khan Academy"}}, {"kind": "read", "req": false, "label": "Dive into Deep Learning, 5.1: sigmoid function and its derivative", "url": "https://d2l.ai/chapter_multilayer-perceptrons/mlp.html#sigmoid-function", "m": 5, "why": "Open it after you have your own answer: the result, the plot of the slope and the maximum of 0.25 at zero."}, {"kind": "video", "req": false, "label": "Derivative of the sigmoid function", "url": "https://www.youtube.com/watch?v=awjXaFR1jOM", "m": 6, "why": "A full derivation to compare with yours after you have tried. Look at how it reaches 1 − σ.", "yt": {"id": "awjXaFR1jOM", "ch": "CampusX"}}, {"kind": "keep", "src": "aieng", "req": false, "label": "AI Engineering from Scratch, phase 1, lesson 05: Chain Rule and Autodiff", "m": 20, "why": "Where sigma times one minus sigma shows up in backprop.", "url": "https://aiengineeringfromscratch.com/lesson?path=phases%2F01-math-foundations%2F05-chain-rule-and-autodiff"}]},
